ALTER TABLE public.prereservations DROP CONSTRAINT prereservations_status_check;
ALTER TABLE public.prereservations ADD CONSTRAINT prereservations_status_check CHECK (status = ANY (ARRAY['draft','pending_approval','approved','declined','expired','cancelled','checkout_hold','confirmed','payment_failed','paid_conflict','amount_review','refunded','substitute_offered','substitute_declined']));
ALTER TABLE public.prereservations ADD CONSTRAINT prereservations_substitute_status_check CHECK (substitute_status IS NULL OR substitute_status = ANY (ARRAY['substitute_offered','substitute_accepted','substitute_declined','substitute_auto_accepted']));